<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\ScoringRulesService;use App\Services\SpecialCategoryService;use App\Services\TestScoringGuardService;
Auth::requireAdmin();
$pdo=Database::connection();$error='';$notice='';
function sx(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function sw(string $table):void{TestScoringGuardService::assertWriteTable($table);}
function col(PDO $pdo,string $table,string $column):bool{$s=$pdo->prepare('SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:t AND COLUMN_NAME=:c');$s->execute(['t'=>$table,'c'=>$column]);return (int)$s->fetchColumn()>0;}
function setup(PDO $pdo):void{
 sw('bdc_test_scoring_rounds');
 if(!col($pdo,'bdc_test_scoring_rounds','scoring_mode'))$pdo->exec("ALTER TABLE bdc_test_scoring_rounds ADD scoring_mode ENUM('manual','automated') NOT NULL DEFAULT 'manual' AFTER division");
 try{$pdo->exec("ALTER TABLE bdc_test_scoring_rounds MODIFY division ENUM('novice','intermediate','advanced','all_star','bachata_rising','bachata_open','bachata_invitational') NOT NULL");}catch(Throwable){}
 sw('bdc_test_scoring_judge_sessions');$pdo->exec("CREATE TABLE IF NOT EXISTS bdc_test_scoring_judge_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,round_id BIGINT UNSIGNED NOT NULL,judge_id BIGINT UNSIGNED NOT NULL,status ENUM('not_started','scoring','submitted') NOT NULL DEFAULT 'not_started',last_saved_at DATETIME NULL,submitted_at DATETIME NULL,UNIQUE KEY uq_test_session(round_id,judge_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
}
function roundRow(PDO $pdo,int $id):?array{$s=$pdo->prepare('SELECT r.*,e.name event_name FROM bdc_test_scoring_rounds r JOIN bdc_test_events e ON e.id=r.event_id WHERE r.id=:id');$s->execute(['id'=>$id]);return $s->fetch()?:null;}
function clearRound(PDO $pdo,int $id):void{foreach(['bdc_test_scoring_judge_sessions','bdc_test_scoring_final_results','bdc_test_scoring_final_marks','bdc_test_scoring_final_pairs','bdc_test_scoring_results','bdc_test_scoring_marks','bdc_test_scoring_judges','bdc_test_scoring_entries','bdc_test_scoring_audit'] as $t){sw($t);try{$pdo->prepare("DELETE FROM `$t` WHERE round_id=:r")->execute(['r'=>$id]);}catch(Throwable){}}sw('bdc_test_scoring_rounds');$pdo->prepare('DELETE FROM bdc_test_scoring_rounds WHERE id=:r')->execute(['r'=>$id]);}
$roundId=(int)($_GET['round_id']??$_POST['round_id']??0);
try{
 setup($pdo);
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$a=(string)($_POST['action']??'');
  if($a==='create'){
   $d=(string)($_POST['division']??'novice');$m=(string)($_POST['mode']??'manual');$rt=(string)($_POST['round_type']??'heats');$allowed=array_merge(['novice','intermediate','advanced'],array_keys(SpecialCategoryService::categories()));if(!in_array($d,$allowed,true)||!in_array($m,['manual','automated'],true)||!in_array($rt,['heats','final'],true))throw new RuntimeException('Invalid test configuration.');
   sw('bdc_test_events');$name='TEST SANDBOX '.date('Y-m-d H:i:s');$slug='test-'.date('YmdHis').random_int(10,99);$pdo->prepare("INSERT INTO bdc_test_events(name,normalised_name,slug,event_date,status) VALUES(:n,:nn,:s,CURDATE(),'draft')")->execute(['n'=>$name,'nn'=>strtolower($name),'s'=>$slug]);$eid=(int)$pdo->lastInsertId();$rule=ScoringRulesService::tierFromRoleCounts(10,10);$w=ScoringRulesService::weights();sw('bdc_test_scoring_rounds');$pdo->prepare("INSERT INTO bdc_test_scoring_rounds(event_id,round_type,division,scoring_mode,yes_count,callback_count,yes_weight,alt1_weight,alt2_weight,alt3_weight,status,created_by) VALUES(:e,:rt,:d,:m,:y,:c,:yw,:a1,:a2,:a3,'draft',:u)")->execute(['e'=>$eid,'rt'=>$rt,'d'=>$d,'m'=>$m,'y'=>$rule['yes_count'],'c'=>$rule['yes_count'],'yw'=>$w['yes'],'a1'=>$w['alt1'],'a2'=>$w['alt2'],'a3'=>$w['alt3'],'u'=>(int)(Auth::user()['id']??0)?:null]);$roundId=(int)$pdo->lastInsertId();$notice='Test created.';
  }elseif($a==='competitors'){
   $r=roundRow($pdo,$roundId);if(!$r)throw new RuntimeException('Test round not found.');$lc=max(1,min(100,(int)($_POST['leaders']??10)));$fc=max(1,min(100,(int)($_POST['followers']??10)));sw('bdc_test_scoring_entries');$pdo->prepare('DELETE FROM bdc_test_scoring_entries WHERE round_id=:r')->execute(['r'=>$roundId]);$ins=$pdo->prepare("INSERT INTO bdc_test_scoring_entries(round_id,competitor_id,dance_role,bib_number,display_name,entry_status) VALUES(:r,:c,:role,:bib,:name,'active')");foreach(['leader'=>$lc,'follower'=>$fc] as $role=>$count){$q=$pdo->prepare("SELECT id,exact_name FROM bdc_competitors WHERE status='active' AND dance_role IN(:role,'both') ORDER BY RAND() LIMIT $count");$q->execute(['role'=>$role]);$bib=1;foreach($q->fetchAll() as $c)$ins->execute(['r'=>$roundId,'c'=>$c['id'],'role'=>$role,'bib'=>$bib++,'name'=>$c['exact_name']]);}if(!SpecialCategoryService::isSpecial((string)$r['division'])){$rule=ScoringRulesService::tierFromRoleCounts($lc,$fc);sw('bdc_test_scoring_rounds');$pdo->prepare('UPDATE bdc_test_scoring_rounds SET yes_count=:y,callback_count=:c WHERE id=:r')->execute(['y'=>$rule['yes_count'],'c'=>$rule['yes_count'],'r'=>$roundId]);}$notice='Real BDC competitors loaded read-only.';
  }elseif($a==='judges'){
   $n=max(3,min(25,(int)($_POST['judges']??5)));sw('bdc_test_scoring_judges');$pdo->prepare('DELETE FROM bdc_test_scoring_judges WHERE round_id=:r')->execute(['r'=>$roundId]);$ins=$pdo->prepare("INSERT INTO bdc_test_scoring_judges(round_id,judge_name,judge_order,is_chief,scoring_scope) VALUES(:r,:n,:o,:c,'all')");for($i=1;$i<=$n;$i++)$ins->execute(['r'=>$roundId,'n'=>'Test Judge '.$i,'o'=>$i,'c'=>$i===1?1:0]);$notice="$n judges generated.";
  }elseif($a==='scores'){
   $r=roundRow($pdo,$roundId);if(!$r)throw new RuntimeException('Round not found.');if($r['round_type']==='final')throw new RuntimeException('Final sandbox scoring is verified by the Automatic Parity Test until the shared Final UI is connected.');$js=$pdo->prepare('SELECT * FROM bdc_test_scoring_judges WHERE round_id=:r ORDER BY judge_order');$js->execute(['r'=>$roundId]);$judges=$js->fetchAll();if(count($judges)<3)throw new RuntimeException('Generate at least 3 judges.');$es=$pdo->prepare("SELECT * FROM bdc_test_scoring_entries WHERE round_id=:r AND entry_status='active'");$es->execute(['r'=>$roundId]);$entries=$es->fetchAll();if(!$entries)throw new RuntimeException('Load competitors first.');sw('bdc_test_scoring_marks');$pdo->prepare('DELETE FROM bdc_test_scoring_marks WHERE round_id=:r')->execute(['r'=>$roundId]);$ins=$pdo->prepare("INSERT INTO bdc_test_scoring_marks(round_id,entry_id,judge_id,mark_type,alt_rank,weighted_score,updated_by) VALUES(:r,:e,:j,:t,:a,:w,:u)");foreach($judges as $j){foreach($entries as $e){$roll=random_int(1,100);$t=$roll<=40?'yes':($roll<=60?'alt':'blank');$alt=$t==='alt'?random_int(1,3):null;$ins->execute(['r'=>$roundId,'e'=>$e['id'],'j'=>$j['id'],'t'=>$t,'a'=>$alt,'w'=>ScoringRulesService::markWeight($t,$alt),'u'=>(int)(Auth::user()['id']??0)?:null]);}if($r['scoring_mode']==='automated'){sw('bdc_test_scoring_judge_sessions');$pdo->prepare("INSERT INTO bdc_test_scoring_judge_sessions(round_id,judge_id,status,last_saved_at,submitted_at) VALUES(:r,:j,'submitted',NOW(),NOW()) ON DUPLICATE KEY UPDATE status='submitted',last_saved_at=NOW(),submitted_at=NOW()")->execute(['r'=>$roundId,'j'=>$j['id']]);}}$notice='Test marks generated with shared BDC weights.';
  }elseif($a==='clear'){$r=roundRow($pdo,$roundId);$eid=(int)($r['event_id']??0);if($r)clearRound($pdo,$roundId);if($eid){sw('bdc_test_events');$pdo->prepare('DELETE FROM bdc_test_events WHERE id=:e')->execute(['e'=>$eid]);}$roundId=0;$notice='Test cleared. Official BDC data unchanged.';}
 }
}catch(Throwable $e){$error=$e->getMessage();}
$r=$roundId?roundRow($pdo,$roundId):null;$csrf=Csrf::token();$counts=['leader'=>0,'follower'=>0];$judgeCount=0;$sessions=0;if($r){$q=$pdo->prepare("SELECT dance_role,COUNT(*) n FROM bdc_test_scoring_entries WHERE round_id=:r AND entry_status='active' GROUP BY dance_role");$q->execute(['r'=>$roundId]);foreach($q->fetchAll() as $x)$counts[$x['dance_role']]=(int)$x['n'];$q=$pdo->prepare('SELECT COUNT(*) FROM bdc_test_scoring_judges WHERE round_id=:r');$q->execute(['r'=>$roundId]);$judgeCount=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM bdc_test_scoring_judge_sessions WHERE round_id=:r AND status='submitted'");$q->execute(['r'=>$roundId]);$sessions=(int)$q->fetchColumn();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Scoring Test Sandbox</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../">BDC Admin</a><a class="btn btn-outline-light btn-sm" href="../">Dashboard</a></div></nav><main class="container py-4"><h1>Scoring Test Sandbox</h1><p class="text-muted">Real BDC data read-only. Test writes are isolated.</p><div class="alert alert-success"><strong>TEST WRITE FIREWALL ACTIVE.</strong> Official points, progression, publications and production scoring cannot be changed here.</div><?php if($error):?><div class="alert alert-danger"><?=sx($error)?></div><?php endif;?><?php if($notice):?><div class="alert alert-info"><?=sx($notice)?></div><?php endif;?><?php if(!$r):?><form method="post" class="card card-body"><input type="hidden" name="_csrf" value="<?=sx($csrf)?>"><input type="hidden" name="action" value="create"><div class="row g-3"><div class="col-md-4"><label>Scoring Mode</label><select class="form-select" name="mode"><option value="manual">Manual</option><option value="automated">Automatic</option></select></div><div class="col-md-4"><label>Category</label><select class="form-select" name="division"><option value="novice">Novice</option><option value="intermediate">Intermediate</option><option value="advanced">Advanced</option><?php foreach(SpecialCategoryService::categories() as $k=>$v):?><option value="<?=sx($k)?>"><?=sx($v)?></option><?php endforeach;?></select></div><div class="col-md-4"><label>Round</label><select class="form-select" name="round_type"><option value="heats">Heats</option><option value="final">Final</option></select></div><div class="col-12"><button class="btn btn-danger">Create Test</button></div></div></form><?php else:?><div class="card card-body mb-3"><strong><?=sx($r['event_name'])?></strong><div><?=strtoupper(sx($r['scoring_mode']))?> · <?=sx(SpecialCategoryService::isSpecial($r['division'])?SpecialCategoryService::label($r['division']):ucfirst($r['division']))?> · <?=sx(ucfirst($r['round_type']))?></div></div><div class="row g-3"><div class="col-md-4"><form method="post" class="card card-body h-100"><input type="hidden" name="_csrf" value="<?=sx($csrf)?>"><input type="hidden" name="action" value="competitors"><input type="hidden" name="round_id" value="<?=$roundId?>"><h2 class="h5">Competitors</h2><div class="row"><div class="col"><input class="form-control" type="number" name="leaders" value="10" min="1" max="100"></div><div class="col"><input class="form-control" type="number" name="followers" value="10" min="1" max="100"></div></div><button class="btn btn-outline-danger mt-2">Load Real BDC Competitors</button><small class="mt-2">Leaders <?=$counts['leader']?> · Followers <?=$counts['follower']?></small></form></div><div class="col-md-4"><form method="post" class="card card-body h-100"><input type="hidden" name="_csrf" value="<?=sx($csrf)?>"><input type="hidden" name="action" value="judges"><input type="hidden" name="round_id" value="<?=$roundId?>"><h2 class="h5">Judges</h2><input class="form-control" type="number" name="judges" value="5" min="3" max="25"><button class="btn btn-outline-dark mt-2">Generate Judges</button><small class="mt-2"><?=$judgeCount?> judges